import { useState } from 'react';

export type Props = { initialName: string; onSubmit: (name: string) => void };

const theme = {
  colors: { panel: '#f2f6fc', text: '#1d3150' },
  spacing: { panel: 16, gap: 8 },
};

export function Component({ initialName, onSubmit }: Props) {
  const [name, setName] = useState(initialName);
  const [reviewing, setReviewing] = useState(false);
  const [invalid, setInvalid] = useState(false);

  return (
    <form
      aria-label="Name wizard"
      data-testid="panel"
      style={{
        backgroundColor: theme.colors.panel,
        color: theme.colors.text,
        padding: theme.spacing.panel,
        display: 'grid',
        gap: theme.spacing.gap,
      }}
      onSubmit={event => {
        event.preventDefault();
        if (reviewing) return;
        const trimmedName = name.trim();
        if (!trimmedName) {
          setInvalid(true);
          return;
        }
        setName(trimmedName);
        setInvalid(false);
        setReviewing(true);
      }}
    >
      {reviewing ? (
        <>
          <output aria-label="Review name">{name}</output>
          <button type="button" onClick={() => setReviewing(false)}>Back</button>
          <button type="button" onClick={() => onSubmit(name)}>Submit</button>
        </>
      ) : (
        <>
          <label>
            Name
            <input
              type="text"
              value={name}
              aria-invalid={invalid || undefined}
              onChange={event => setName(event.currentTarget.value)}
            />
          </label>
          {invalid && <p role="alert">Name required</p>}
          <button type="submit">Next</button>
        </>
      )}
    </form>
  );
}
